#include "hip_api.h"
#include <fstream>
#include <sstream>
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("resources MODULESET CASES_CSV");Api api;api.Check(api.hipInit(0),"init");api.Check(api.hipSetDevice(0),"device");using Occ=int(*)(int*,Handle,int,size_t);using Attr=int(*)(int*,int,Handle);Occ occ{};Attr attr{};api.Load(occ,"hipModuleOccupancyMaxActiveBlocksPerMultiprocessor");api.Load(attr,"hipFuncGetAttribute");auto props=api.Properties(0);printf("device=%s MP=%d LDS=%zu\n",props.name,props.multiProcessorCount,props.sharedMemPerMultiprocessor);std::ifstream input(argv[2]);if(!input)throw std::runtime_error("cases file");std::string line;while(std::getline(input,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty())continue;std::stringstream s(line);std::string set,module,kernel,threads;std::getline(s,set,',');std::getline(s,module,',');std::getline(s,kernel,',');std::getline(s,threads,',');Handle m{},f{};auto path=std::string(argv[1])+"/modules-"+set+"/gfx1201/"+module+".hsaco";api.Check(api.LoadModule(&m,path.c_str()),"module");api.Check(api.hipModuleGetFunction(&f,m,kernel.c_str()),"kernel");int b=0,v=0,l=0,p=0;api.Check(occ(&b,f,std::stoi(threads),0),"occupancy");api.Check(attr(&v,4,f),"regs");api.Check(attr(&l,1,f),"lds");api.Check(attr(&p,3,f),"private");printf("%s,%s,%s,%s,%d,%d,%d,%d\n",set.c_str(),module.c_str(),kernel.c_str(),threads.c_str(),v,l,p,b);api.hipModuleUnload(m);}return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
